Uniform voting : fn majority_vote(&self, neighbors: &[(f32, usize)]) -> usize { let mut counts = HashMap::new(); for (_dist, label) in neighbors { *counts.entry(*label).or_insert(0) += 1; } *counts.iter().max_by_key(|(_, &count)| count).unwrap().0
} Weighted voting : fn weighted_vote(&self, neighbors: &[(f32, usize)]) -> usize { let mut weights = HashMap::new(); for (dist, label) in neighbors { let weight = if *dist < 1e-10 { 1.0 } else { 1.0 / dist }; *weights.entry(*label).or_insert(0.0) += weight; } *weights.iter().max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap()).unwrap().0
}

