#[derive(Debug, Clone)]
pub struct KFold { n_splits: usize, shuffle: bool, random_state: Option<u64>,
} impl KFold { pub fn new(n_splits: usize) -> Self { Self { n_splits, shuffle: false, random_state: None, } } pub fn with_shuffle(mut self, shuffle: bool) -> Self { self.shuffle = shuffle; self } pub fn with_random_state(mut self, random_state: u64) -> Self { self.random_state = Some(random_state); self.shuffle = true; self } pub fn split(&self, n_samples: usize) -> Vec<(Vec<usize>, Vec<usize>)> { let mut indices: Vec<usize> = (0..n_samples).collect(); if self.shuffle { if let Some(seed) = self.random_state { let mut rng = rand::rngs::StdRng::seed_from_u64(seed); indices.shuffle(&mut rng); } else { indices.shuffle(&mut rand::thread_rng()); } } let fold_sizes = calculate_fold_sizes(n_samples, self.n_splits); let mut splits = Vec::with_capacity(self.n_splits); let mut start_idx = 0; for &fold_size in &fold_sizes { let test_indices = indices[start_idx..start_idx + fold_size].to_vec(); let mut train_indices = Vec::new(); train_indices.extend_from_slice(&indices[..start_idx]); train_indices.extend_from_slice(&indices[start_idx + fold_size..]); splits.push((train_indices, test_indices)); start_idx += fold_size; } splits }
} fn calculate_fold_sizes(n_samples: usize, n_splits: usize) -> Vec<usize> { let base_size = n_samples / n_splits; let remainder = n_samples % n_splits; let mut sizes = vec![base_size; n_splits]; for i in 0..remainder { sizes[i] += 1; } sizes
} Verification: $ cargo test kfold
