#[derive(Debug, Clone)]
pub struct CrossValidationResult { pub scores: Vec<f32>,
} impl CrossValidationResult { pub fn mean(&self) -> f32 { self.scores.iter().sum::<f32>() / self.scores.len() as f32 } pub fn std(&self) -> f32 { let mean = self.mean(); let variance = self.scores .iter() .map(|&score| (score - mean).powi(2)) .sum::<f32>() / self.scores.len() as f32; variance.sqrt() } pub fn min(&self) -> f32 { self.scores .iter() .cloned() .fold(f32::INFINITY, f32::min) } pub fn max(&self) -> f32 { self.scores .iter() .cloned() .fold(f32::NEG_INFINITY, f32::max) }
} pub fn cross_validate<E>( estimator: &E, x: &Matrix<f32>, y: &Vector<f32>, cv: &KFold,
) -> Result<CrossValidationResult, String>
where E: Estimator + Clone,
{ let n_samples = x.shape().0; let splits = cv.split(n_samples); let mut scores = Vec::with_capacity(splits.len()); for (train_idx, test_idx) in splits { let (x_train, y_train) = extract_samples(x, y, &train_idx); let (x_test, y_test) = extract_samples(x, y, &test_idx); let mut fold_model = estimator.clone(); fold_model.fit(&x_train, &y_train)?; let score = fold_model.score(&x_test, &y_test); scores.push(score); } Ok(CrossValidationResult { scores })
} Verification: $ cargo test cross_validate
